-- 신청·제출본·서류는 서로 다른 생명주기를 갖는다. 제출본에서 현재 파일을 다시 조회하지 않는다.
CREATE TABLE demo_scenario (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(30) NOT NULL UNIQUE, fixture_version VARCHAR(30) NOT NULL, description VARCHAR(500) NOT NULL);
CREATE TABLE workspace (id BIGINT PRIMARY KEY AUTO_INCREMENT, kind VARCHAR(20) NOT NULL, session_token_hash CHAR(64) UNIQUE, scenario_id BIGINT, expires_at DATETIME(6), created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(scenario_id) REFERENCES demo_scenario(id), CHECK(kind IN ('NORMAL','DEMO')));
CREATE TABLE app_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, workspace_id BIGINT NOT NULL, login_id VARCHAR(100) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, display_name VARCHAR(50) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(workspace_id) REFERENCES workspace(id));
CREATE TABLE role (code VARCHAR(20) PRIMARY KEY, name VARCHAR(50) NOT NULL);
CREATE TABLE user_role (user_id BIGINT NOT NULL, role_code VARCHAR(20) NOT NULL, PRIMARY KEY(user_id,role_code), FOREIGN KEY(user_id) REFERENCES app_user(id), FOREIGN KEY(role_code) REFERENCES role(code));
CREATE TABLE program (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(200) NOT NULL, body TEXT NOT NULL, status VARCHAR(20) NOT NULL, opens_at DATETIME(6) NOT NULL, closes_at DATETIME(6) NOT NULL, max_amount DECIMAL(12,0) NOT NULL, version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), CHECK(opens_at < closes_at), CHECK(max_amount > 0));
CREATE TABLE program_document_rule (id BIGINT PRIMARY KEY AUTO_INCREMENT, program_id BIGINT NOT NULL, type_code VARCHAR(30) NOT NULL, required BOOLEAN NOT NULL DEFAULT TRUE, max_bytes BIGINT NOT NULL DEFAULT 10485760, allowed_mime VARCHAR(100) NOT NULL DEFAULT 'image/png,image/jpeg', UNIQUE(program_id,type_code), FOREIGN KEY(program_id) REFERENCES program(id));
CREATE TABLE application (id BIGINT PRIMARY KEY AUTO_INCREMENT, workspace_id BIGINT NOT NULL, program_id BIGINT NOT NULL, owner_id BIGINT NOT NULL, receipt_no VARCHAR(40) UNIQUE, status VARCHAR(30) NOT NULL DEFAULT 'DRAFT', business_name VARCHAR(100), business_no CHAR(10), representative VARCHAR(50), opened_on DATE, phone VARCHAR(20), plan_text TEXT, requested_amount DECIMAL(12,0), submitted_at DATETIME(6), updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), version BIGINT NOT NULL DEFAULT 0, UNIQUE(workspace_id,program_id,owner_id), FOREIGN KEY(workspace_id) REFERENCES workspace(id), FOREIGN KEY(program_id) REFERENCES program(id), FOREIGN KEY(owner_id) REFERENCES app_user(id), CHECK(status IN ('DRAFT','SUBMITTED','UNDER_REVIEW','NEEDS_SUPPLEMENT','APPROVED','REJECTED')), CHECK(requested_amount IS NULL OR requested_amount BETWEEN 1 AND 10000000));
CREATE TABLE staff_assignment (id BIGINT PRIMARY KEY AUTO_INCREMENT, application_id BIGINT NOT NULL UNIQUE, staff_id BIGINT NOT NULL, assigned_by BIGINT NOT NULL, reason VARCHAR(1000) NOT NULL, assigned_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(application_id) REFERENCES application(id), FOREIGN KEY(staff_id) REFERENCES app_user(id), FOREIGN KEY(assigned_by) REFERENCES app_user(id));
CREATE TABLE document (id BIGINT PRIMARY KEY AUTO_INCREMENT, application_id BIGINT NOT NULL, type_code VARCHAR(30) NOT NULL, version INT NOT NULL, storage_key VARCHAR(255) NOT NULL UNIQUE, original_name VARCHAR(255) NOT NULL, mime_type VARCHAR(100) NOT NULL, size_bytes BIGINT NOT NULL, sha256 CHAR(64) NOT NULL, created_by BIGINT NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), UNIQUE(application_id,type_code,version), FOREIGN KEY(application_id) REFERENCES application(id), FOREIGN KEY(created_by) REFERENCES app_user(id), CHECK(type_code IN ('BUSINESS_CERT','ESTIMATE')), CHECK(size_bytes BETWEEN 1 AND 10485760));
CREATE TABLE application_revision (id BIGINT PRIMARY KEY AUTO_INCREMENT, application_id BIGINT NOT NULL, revision_no INT NOT NULL, snapshot JSON NOT NULL, submitted_by BIGINT NOT NULL, submitted_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), UNIQUE(application_id,revision_no), FOREIGN KEY(application_id) REFERENCES application(id), FOREIGN KEY(submitted_by) REFERENCES app_user(id));
CREATE TABLE revision_document (revision_id BIGINT NOT NULL, document_id BIGINT NOT NULL, PRIMARY KEY(revision_id,document_id), FOREIGN KEY(revision_id) REFERENCES application_revision(id), FOREIGN KEY(document_id) REFERENCES document(id));
CREATE TABLE submission_command (id BIGINT PRIMARY KEY AUTO_INCREMENT, application_id BIGINT NOT NULL, idempotency_key VARCHAR(64) NOT NULL, payload_hash CHAR(64) NOT NULL, revision_id BIGINT NOT NULL, UNIQUE(application_id,idempotency_key), FOREIGN KEY(application_id) REFERENCES application(id), FOREIGN KEY(revision_id) REFERENCES application_revision(id));
CREATE TABLE ocr_job (id BIGINT PRIMARY KEY AUTO_INCREMENT, document_id BIGINT NOT NULL, provider_mode VARCHAR(10) NOT NULL DEFAULT 'SAMPLE', provider_version VARCHAR(50) NOT NULL DEFAULT 'sample-v1', status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, next_attempt_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), lease_until DATETIME(6), claim_token VARCHAR(64), error_code VARCHAR(50), created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), UNIQUE(document_id,provider_mode,provider_version), FOREIGN KEY(document_id) REFERENCES document(id));
CREATE TABLE ocr_result (id BIGINT PRIMARY KEY AUTO_INCREMENT, job_id BIGINT NOT NULL UNIQUE, extracted_fields JSON NOT NULL, confidence JSON, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(job_id) REFERENCES ocr_job(id));
CREATE TABLE field_confirmation (id BIGINT PRIMARY KEY AUTO_INCREMENT, document_id BIGINT NOT NULL, ocr_result_id BIGINT, field_code VARCHAR(30) NOT NULL, confirmed_value VARCHAR(200) NOT NULL, confirmed_by BIGINT NOT NULL, confirmed_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), UNIQUE(document_id,field_code), FOREIGN KEY(document_id) REFERENCES document(id), FOREIGN KEY(ocr_result_id) REFERENCES ocr_result(id), FOREIGN KEY(confirmed_by) REFERENCES app_user(id));
CREATE TABLE review (id BIGINT PRIMARY KEY AUTO_INCREMENT, application_id BIGINT NOT NULL UNIQUE, reviewer_id BIGINT NOT NULL, check_items JSON NOT NULL, decision VARCHAR(20), reason VARCHAR(1000), updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(application_id) REFERENCES application(id), FOREIGN KEY(reviewer_id) REFERENCES app_user(id));
CREATE TABLE supplement_request (id BIGINT PRIMARY KEY AUTO_INCREMENT, application_id BIGINT NOT NULL, requested_by BIGINT NOT NULL, reason VARCHAR(1000) NOT NULL, due_at DATETIME(6) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(application_id) REFERENCES application(id), FOREIGN KEY(requested_by) REFERENCES app_user(id));
CREATE TABLE supplement_item (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id BIGINT NOT NULL, target_code VARCHAR(50) NOT NULL, instruction VARCHAR(1000) NOT NULL, UNIQUE(request_id,target_code), FOREIGN KEY(request_id) REFERENCES supplement_request(id));
CREATE TABLE supplement_response (id BIGINT PRIMARY KEY AUTO_INCREMENT, request_id BIGINT NOT NULL UNIQUE, revision_id BIGINT NOT NULL, response_text VARCHAR(2000) NOT NULL, responded_by BIGINT NOT NULL, responded_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(request_id) REFERENCES supplement_request(id), FOREIGN KEY(revision_id) REFERENCES application_revision(id), FOREIGN KEY(responded_by) REFERENCES app_user(id));
CREATE TABLE application_status_history (id BIGINT PRIMARY KEY AUTO_INCREMENT, application_id BIGINT NOT NULL, from_status VARCHAR(30), to_status VARCHAR(30) NOT NULL, actor_id BIGINT NOT NULL, reason VARCHAR(1000), created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(application_id) REFERENCES application(id), FOREIGN KEY(actor_id) REFERENCES app_user(id));
CREATE TABLE audit_event (id BIGINT PRIMARY KEY AUTO_INCREMENT, workspace_id BIGINT NOT NULL, actor_id BIGINT NOT NULL, application_id BIGINT, action VARCHAR(50) NOT NULL, target_type VARCHAR(30) NOT NULL, target_id BIGINT NOT NULL, request_id VARCHAR(64) NOT NULL, summary VARCHAR(1000) NOT NULL, created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6), FOREIGN KEY(workspace_id) REFERENCES workspace(id), FOREIGN KEY(actor_id) REFERENCES app_user(id), FOREIGN KEY(application_id) REFERENCES application(id));
CREATE INDEX ix_application_queue ON application(workspace_id,program_id,status,submitted_at,id);
CREATE INDEX ix_application_owner ON application(workspace_id,owner_id,updated_at,id);
CREATE INDEX ix_assignment_staff ON staff_assignment(staff_id,application_id);
CREATE INDEX ix_supplement_due ON supplement_request(status,due_at,application_id);
CREATE INDEX ix_ocr_pending ON ocr_job(status,next_attempt_at,id);
CREATE INDEX ix_ocr_lease ON ocr_job(status,lease_until,id);
CREATE INDEX ix_history_time ON application_status_history(application_id,created_at,id);
CREATE INDEX ix_audit_scope ON audit_event(workspace_id,created_at,id);
